package net.officefloor.hq.app.period;

import jakarta.servlet.http.HttpServletRequest;
import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.setting.SettingsRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Makes the twelve monthly periods of fiscal year FY<yyyy>, from the first day of the sheet's fiscal
 * start month in that year, exactly as the period generator does: a month whose name is already a
 * period, or whose days overlap a period on the sheet, is left out; each made is saved and audited.
 */
public class GenerateFiscalYear {
    public void generate(@Val FiscalYear fiscalYear, @Val Sheet sheet, SettingsRepository settings,
            PeriodRepository repository, HttpServletRequest request, Audit audit, Out<GeneratePeriodsResponse> result) {
        LocalDate from = LocalDate.of(fiscalYear.year(), settings.find(sheet.id()).fiscalStart(), 1);
        result.set(new GeneratePeriodsResponse(
                GeneratePeriods.months(from, from.plusMonths(12).minusDays(1), sheet, repository, request, audit)));
    }
}
package net.officefloor.hq.app.period;

/** A fiscal year to generate monthly periods for, as the screen sends it: its name's year (yyyy). */
public record GenerateFiscalYearRequest(String year) {
}
package net.officefloor.hq.app.period;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateGenerateFiscalYear {
    public void validate(@RequestBody GenerateFiscalYearRequest request, Out<FiscalYear> fiscalYear)
            throws InvalidPeriodException {
        String value = request == null || request.year() == null ? "" : request.year().trim();
        if (!value.matches("\\d{4}")) throw new InvalidPeriodException("A fiscal year is a year, yyyy");
        fiscalYear.set(new FiscalYear(Integer.parseInt(value)));
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithGeneratedPeriods {
    public void respond(@Val GeneratePeriodsResponse result, ObjectResponse<GeneratePeriodsResponse> response) {
        response.send(result);
    }
}
package net.officefloor.hq.app.period;

/** How many monthly periods were made. */
public record GeneratePeriodsResponse(int made) {
}
# Generate a fiscal year's twelve monthly periods. Validate first so a bad year is a 400, not a 404.
# A viewer may change nothing: refused before anything is read or written.
viewer:
  class: net.officefloor.hq.app.role.CheckCanChange
  next: validate
validate:
  class: net.officefloor.hq.app.period.ValidateGenerateFiscalYear
  next: load
load:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: generate
# From the first day of the sheet's fiscal start month in the year, as the period generator does.
generate:
  class: net.officefloor.hq.app.period.GenerateFiscalYear
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.period.RespondWithGeneratedPeriods
  govern: [ transaction ]

